def validate(x,sc,path='$'):
 typ=sc.get('type')
 if typ=='object':
  assert isinstance(x,dict),path
  assert set(sc.get('required',[]))<=set(x),path
  if sc.get('additionalProperties')==False:assert set(x)<=set(sc['properties']),path
  for k,v in x.items():
   if k in sc.get('properties',{}):validate(v,sc['properties'][k],path+'.'+k)
 elif typ=='array':
  assert isinstance(x,list) and len(x)>=sc.get('minItems',0),path
  for i,v in enumerate(x):validate(v,sc['items'],path+str(i))
 elif typ=='string': assert isinstance(x,str) and len(x)>=sc.get('minLength',0),path
 elif typ=='integer':assert isinstance(x,int) and not isinstance(x,bool),path
 elif typ=='number':assert isinstance(x,(float,int)),path
 if 'enum' in sc:assert x in sc['enum'],path
 if 'minimum'in sc:assert x>=sc['minimum'],path
 if 'maximum'in sc:assert x<=sc['maximum'],path
